function mergeSorted(a: ListNode | null, b: ListNode | null): ListNode | null {
  const vals: number[] = [];
  for (let n = a; n; n = n.next) vals.push(n.val);
  for (let n = b; n; n = n.next) vals.push(n.val);
  vals.sort((x, y) => x - y);
  let out: ListNode | null = null;
  for (let i = vals.length - 1; i >= 0; i--) out = new ListNode(vals[i], out);
  return out;
}

