class Solution:
    def mergeSorted(self, a: Optional[ListNode], b: Optional[ListNode]) -> Optional[ListNode]:
        vals = []
        for h in (a, b):
            while h:
                vals.append(h.val)
                h = h.next
        out = None
        for v in sorted(vals, reverse=True):
            out = ListNode(v, out)
        return out

